+  }
+  save_diagnostic(
+    stage,
+    "failed",
+    error_type~,
+    phase~,
+    tunnel_directory=directory,
+    error_message=detail,
+    evidence={ "workspaceId": required(state, "workspaceId") },
+    environment=workspace_environment(state),
+    protected_secrets=secrets,
+    recording=true,
