fn diagnostic_error(
  error : Error,
  environment? : Map[String, String],
) -> String {
  let (message, omitted) = match error {
    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
  diagnostic_text(message, environment?, omitted~)
}

///|
fn diagnostic_text(
  message : String,
  environment? : Map[String, String],
  omitted~ : Bool = false,
  protected_secrets? : Array[String],
  incomplete_final_line~ : Bool = false,
) -> String {
  let progress = Progress::new("diagnostic-error", environment?)
  if protected_secrets is Some(values) {
    for value in values {
      add_protected_secret(progress.secrets, value)
    }
  }
  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
  let lines = []
  let mut incomplete = omitted
  let source_lines = message.split("\n").to_array()
  for index in 0..<source_lines.length() {
    let line = source_lines[index]
    if lines.length() == 32 {
      incomplete = true
      ignore(lines.remove(1))
    }
    let truncated = line.length() > 1024
    let bounded = if truncated {
      incomplete = true
      line[:1024].to_owned()
    } else {
      line.to_owned()
    }
    let bounded = if truncated ||
      (incomplete_final_line && index == source_lines.length() - 1) {
      diagnostic_partial_secret(bounded, progress.secrets)
    } else {
      bounded
    }
    match progress.safe_message(bounded) {
      Some(safe) => lines.push(safe)
      None => {
        incomplete = true
        lines.push("[unavailable]")
      }
    }
  }
  if (incomplete || progress.details_truncated) &&
    lines.last() != Some("[error details incomplete or truncated]") {
    lines.push("[error details incomplete or truncated]")
  }
  lines.join("\n")
}

///|
fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let mut boundary = chars.length()
  for secret in secrets {
    let value = secret.iter().to_array()
    if value.length() == 0 || text.has_suffix(secret) {
      continue
    }
    let limit = if value.length() - 1 < boundary {
      value.length() - 1
    } else {
      boundary
    }
    if limit == 0 {
      continue
    }
    let prefixes = FixedArray::make(limit, 0)
    let mut matched = 0
    for index in 1..<limit {
      while matched > 0 && value[matched] != value[index] {
        matched = prefixes[matched - 1]
      }
      if value[matched] == value[index] {
        matched += 1
      }
      prefixes[index] = matched
    }
    matched = 0
    for index in 0..<boundary {
      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
        matched = prefixes[matched - 1]
      }
      if matched < limit && value[matched] == chars[index] {
        matched += 1
      }
    }
    boundary -= matched
  }
  if boundary == chars.length() {
    text
  } else {
    character_text(chars, 0, boundary) + "[redacted]"
  }
}

///|
priv struct DiagnosticProtectedValues {
  secrets : Array[String]
  mut visited : Int32
  mut incomplete : Bool
}

///|
fn diagnostic_add_protected(
  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      !output.contains(value) &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
    ) {
    return
  }
  if result.secrets.length() >= 512 {
    result.incomplete = true
    return
  }
  destination.push(value)
}

///|
fn diagnostic_protected_values(
  value : Json,
  result : DiagnosticProtectedValues,
  output : String,
  uncertain : Bool,
  secret~ : Bool = false,
  depth~ : Int32 = 0,
) -> Unit {
  if result.visited >= 65536 || depth >= 64 {
    result.incomplete = true
    return
  }
  result.visited += 1
  match value {
    Json::String(text) if text != "" && secret => {
      let destination = result.secrets
      diagnostic_add_protected(text, output, uncertain, destination, result)
      for line in text.split("\n") {
        if line != "" && line.length() < text.length() {
          diagnostic_add_protected(
            line.to_owned(),
            output,
            uncertain,
            destination,
            result,
          )
        }
        for word in line.split(" ") {
          for part in word.split("=") {
            if part != "" && part.length() < text.length() {
              diagnostic_add_protected(
                part.to_owned(),
                output,
                uncertain,
                destination,
                result,
              )
            }
          }
        }
      }
      let escaped = Json::string(text).stringify()
      if escaped.length() > 2 {
        let encoded = escaped[1:escaped.length() - 1].to_owned()
        if encoded != text {
          diagnostic_add_protected(
            encoded, output, uncertain, destination, result,
          )
        }
      }
    }
    Json::String(text) if text != "" => {
      let mut next_secret = false
      for word in text.split(" ") {
        let word = word.to_owned()
        if next_secret {
          diagnostic_add_protected(
            word,
            output,
            uncertain,
            result.secrets,
            result,
          )
          next_secret = false
        } else if word.split_once("=") is Some((name, value)) {
          if credential_field(name.to_owned(), for_diagnostics=true) {
            diagnostic_add_protected(
              value.to_owned(),
              output,
              uncertain,
              result.secrets,
              result,
            )
          }
        } else if word.has_prefix("-") &&
          credential_field(word, for_diagnostics=true) {
          next_secret = true
        }
      }
    }
    Json::Array(values) =>
      for item in values {
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret~,
          depth=depth + 1,
        )
      }
    Json::Object(values) =>
      for name, item in values {
        let key = name.to_lower().replace_all(old="_", new="")
        diagnostic_protected_values(
          item,
          result,
          output,
          uncertain,
          secret=secret ||
            credential_field(name, for_diagnostics=true) ||
            key == "pairingcode",
          depth=depth + 1,
        )
      }
    _ => ()
  }
}

///|
fn diagnostic_output(
  output : Bytes,
  environment : Map[String, String],
  protected_input? : String,
  protect_all_input~ : Bool = false,
  protected_secrets? : Array[String],
  omitted~ : Bool = false,
) -> String? {
  if output.length() == 0 {
    return if omitted {
      Some("[error details incomplete or truncated]")
    } else {
      None
    }
  }
  let limit = if output.length() > 8192 { 8192 } else { output.length() }
  let incomplete = omitted || limit < output.length()
  let text = @utf8.decode_lossy(output[:limit])
  let safeguards : DiagnosticProtectedValues = {
    secrets: [],
    visited: 0,
    incomplete: false,
  }
  if protected_input is Some(input) {
    diagnostic_protected_values(
      @json.parse(input),
      safeguards,
      text,
      incomplete,
      secret=protect_all_input,
    ) catch {
      _ => safeguards.incomplete = true
    }
  }
  if safeguards.incomplete {
    return Some(
      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
    )
  }
  Some(
    diagnostic_text(
      text,
      environment~,
      omitted=incomplete,
      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
    ),
  )
}

///|
fn incomplete_diagnostic_detail(detail : String?) -> String {
  let detail = detail.unwrap_or("")
  if detail.contains("[error details incomplete or truncated]") {
    detail
  } else {
    detail +
    (if detail == "" { "" } else { "\n" }) +
    "[error details incomplete or truncated]"
  }
}

///|
priv struct DiagnosticCapture {
  output : @buffer.Buffer
  limit : Int32
  mut truncated : Bool
  mut finished : Bool
}

///|
fn DiagnosticCapture::new(limit : Int32) -> DiagnosticCapture {
  {
    output: @buffer.Buffer(size_hint=if limit < 4096 { limit } else { 4096 }),
    limit,
    truncated: false,
    finished: false,
  }
}

///|
async fn DiagnosticCapture::read(
  self : DiagnosticCapture,
  reader : @process.ReadFromProcess,
) -> Unit {
  try {
    while reader.read_some(max_len=4096) is Some(chunk) {
      let remaining = self.limit - self.output.length()
      let count = if chunk.length() < remaining {
        chunk.length()
      } else {
        remaining
      }
      if count > 0 {
        self.output.write_bytes(chunk[:count])
      }
      if count < chunk.length() {
        self.truncated = true
      }
    }
  } catch {
    error =>
      if @async.is_being_cancelled() {
        raise error
      } else {
        self.truncated = true
      }
  }
  self.finished = true
}

///|
async fn wait_diagnostic_captures(captures : Array[DiagnosticCapture]) -> Unit {
  @async.with_timeout(250, async fn() {
    while captures.iter().any(capture => !capture.finished) {
      @async.sleep(5)
    }
  }) catch {
    error => if @async.is_being_cancelled() { raise error }
  }
}

///|
async fn diagnostic_process_output(
  program : String,
  args : Array[String],
  environment~ : Map[String, String],
  cwd? : StringView,
  stdin? : &@process.ProcessInput,
  stdout_limit~ : Int32,
  stderr_limit~ : Int32,
) -> (Int32, Bytes, Bool, Bytes, Bool) {
  let (out, stdout) = @process.read_from_process()
  defer out.close()
  let (err, stderr) = @process.read_from_process()
  defer err.close()
  @async.with_task_group(async fn(group) {
    let child = @process.spawn(
      group,
      program,
      args,
      extra_env=environment,
      inherit_env=false,
      cwd?,
      stdin?,
      stdout~,
      stderr~,
    )
    let output = DiagnosticCapture::new(stdout_limit)
    let errors = DiagnosticCapture::new(stderr_limit)
    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
    let status = child.wait()
    if status == 0 {
      while !output.finished {
        @async.sleep(5)
      }
      wait_diagnostic_captures([errors])
    } else {
      wait_diagnostic_captures([output, errors])
    }
    (
      status,
      output.output.to_bytes(),
      output.truncated || !output.finished,
      errors.output.to_bytes(),
      errors.truncated || !errors.finished,
    )
  })
}

///|
async fn save_command_failure(
  stage : String,
  error : Error,
  recording? : Bool,
  phase? : String,
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  let cancelled = @async.is_being_cancelled()
  let timeout = error is @async.TimeoutError
  save_diagnostic(
    stage,
    if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else {
      "failed"
    },
    error_type=if cancelled {
      "cancelled"
    } else if timeout {
      "timeout"
    } else if error is InvalidConfig(_) {
      "invalid_config"
    } else if error is AdapterError(_) {
      "adapter_error"
    } else if error is @os_error.OSError(_, ..) {
      "os_error"
    } else {
      "unexpected_error"
    },
    os_errno?=match error {
      @os_error.OSError(code, ..) => Some(code)
      _ => None
    },
    phase?,
    error_message=diagnostic_error(error),
    recording?,
  )
}

