///|
let recording_run_id : String = @env.now().to_string() +
  "_" +
  proxy_pid().to_string()

///|
fn diagnostic_error(
  error : Error,
  environment? : Map[String, String],
) -> String {
  let (message, omitted) = match error {
    AdapterError(detail) => (detail, false)
    InvalidConfig(detail) => (detail, false)
    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
    @json.InvalidNumber(position, _) =>
      (
        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
        true,
      )
    _ => (error.to_string(), false)
  }
  diagnostic_text(message, environment?, omitted~)
}

///|
fn diagnostic_text(
  message : String,
  environment? : Map[String, String],
  omitted~ : Bool = false,
  protected_secrets? : Array[String],
  incomplete_final_line~ : Bool = false,
) -> String {
  let progress = Progress::new("diagnostic-error", environment?)
  if protected_secrets is Some(values) {
    for value in values {
      add_protected_secret(progress.secrets, value)
    }
  }
  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
  let lines = []
  let mut incomplete = omitted
  let source_lines = message.split("\n").to_array()
  for index in 0..<source_lines.length() {
    let line = source_lines[index]
    if lines.length() == 32 {
      incomplete = true
      ignore(lines.remove(1))
    }
    let truncated = line.length() > 1024
    let bounded = if truncated {
      incomplete = true
      line[:1024].to_owned()
    } else {
      line.to_owned()
    }
    let bounded = if truncated ||
      (incomplete_final_line && index == source_lines.length() - 1) {
      diagnostic_partial_secret(bounded, progress.secrets)
    } else {
      bounded
    }
    match progress.safe_message(bounded) {
      Some(safe) => lines.push(safe)
      None => {
        incomplete = true
        lines.push("[unavailable]")
      }
    }
  }
  if (incomplete || progress.details_truncated) &&
    lines.last() != Some("[error details incomplete or truncated]") {
    lines.push("[error details incomplete or truncated]")
  }
  lines.join("\n")
}

///|
fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
  let chars = text.iter().to_array()
  let mut boundary = chars.length()
  for secret in secrets {
    let value = secret.iter().to_array()
    if value.length() == 0 || text.has_suffix(secret) {
      continue
    }
    let limit = if value.length() - 1 < boundary {
      value.length() - 1
    } else {
      boundary
    }
    if limit == 0 {
      continue
    }
    let prefixes = FixedArray::make(limit, 0)
    let mut matched = 0
    for index in 1..<limit {
      while matched > 0 && value[matched] != value[index] {
        matched = prefixes[matched - 1]
      }
      if value[matched] == value[index] {
        matched += 1
      }
      prefixes[index] = matched
    }
    matched = 0
    for index in 0..<boundary {
      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
        matched = prefixes[matched - 1]
      }
      if matched < limit && value[matched] == chars[index] {
        matched += 1
      }
    }
    boundary -= matched
  }
  if boundary == chars.length() {
    text
  } else {
    character_text(chars, 0, boundary) + "[redacted]"
  }
}

