///|
async fn command_result(
  program : String,
  args : Array[String],
  stage : String,
  environment? : Map[String, String],
  cwd? : StringView,
  target? : String,
  recording_override? : Bool,
  protected_secrets? : Array[String],
  protection_incomplete~ : Bool = false,
) -> (Int32, String, String) {
  let recording = recording_override.unwrap_or(
    environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
    Some("0"),
  )
  let context : Json? = if recording {
    diagnostic_operation_counter.val += 1
    let value : Json = {
      "operationId": recording_run_id +
      ":" +
      diagnostic_operation_counter.val.to_string(),
    }
    if target is Some(id) {
      set_field(value, "workspaceId", Json::string(id))
    }
    Some(value)
  } else {
    None
  }
  save_diagnostic(
    stage,
    "started",
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets?,
    recording~,
  )
  let started = @env.now()
  let progress = Progress::new(
    stage,
    environment?,
    context?,
    recording_override=recording,
    protected_secrets?,
    protection_incomplete~,
  )
  let label = target.map(value => value + ": " + stage).unwrap_or(stage)
  progress_message(label + ": running…")
  let mut failure_kind = "process_api"
  let mut failure_errno = None
  let mut failure_phase = None
  let (status, output, errors) = {
    errdefer {
      save_diagnostic(
        stage,
        if @async.is_being_cancelled() {
          "cancelled"
        } else {
          "process-error"
        },
        error_type=failure_kind,
        os_errno?=failure_errno,
        phase?=failure_phase,
        error_message=progress.failure_detail(),
        details_truncated=progress.details_truncated,
        evidence?=context,
        evidence_stable_operation=true,
        environment?,
        protected_secrets?,
        recording~,
      )
      progress_message(label + ": failed (" + progress_timing(started) + ")")
    }
    try {
      let (out, stdout) = @process.read_from_process()
      defer out.close()
      let (err, stderr) = @process.read_from_process()
      defer err.close()
      @async.with_task_group(async fn(group) {
        let child = @process.spawn(
          group,
          program,
          args,
          extra_env?=environment,
          inherit_env=environment is None,
          cwd?,
          stdout~,
          stderr~,
        )
        let output = group.spawn(async fn() {
          progress.read_output(
            out,
            capture=true,
            statuses=devsy_progress_stage(stage),
            messages=stage == "orca-install" || stage == "checkout-workspace",
          )
        })
        let errors = group.spawn(async fn() {
          progress.read_output(
            err,
            capture=false,
            messages=devsy_progress_stage(stage) ||
              stage == "orca-install" ||
              stage == "checkout-workspace",
          )
        })
        (child.wait(), output.wait(), errors.wait())
      })
    } catch {
      @os_error.OSError(code, ..) as error => {
        failure_kind = "process_os"
        failure_errno = Some(code)
        let message = if protection_incomplete {
          progress.details_truncated = true
          "subprocess OS error \{code}; workspace protection values unavailable"
        } else {
          progress
          .safe_message(program + ": " + error.to_string())
          .unwrap_or("subprocess OS error \{code}")
        }
        progress.remember(message, warning=true)
        raise AdapterError(
          "\{stage} failed (OS error \{code}); diagnostic run \{recording_run_id}:\n" +
          message,
        )
      }
      @utf8.Malformed(_) => {
        failure_kind = "process_utf8"
        failure_phase = Some("read")
        progress.remember("subprocess output is not valid UTF-8", warning=true)
        raise AdapterError(
          "\{stage} failed: subprocess output is not valid UTF-8; diagnostic run \{recording_run_id}",
        )
      }
      error => {
        if !@async.is_being_cancelled() {
          let detail = if protection_incomplete {
            progress.details_truncated = true
            "error detail unavailable because workspace protection values could not be read"
          } else {
            diagnostic_text(
              diagnostic_error(error, environment?),
              environment?,
              protected_secrets=progress.secrets,
            )
          }
          for line in detail.split("\n") {
            progress.remember(line.to_owned(), warning=true)
          }
        }
        raise error
      }
    }
  }
  let output_secrets = [] + progress.secrets
  let mut output_protection_incomplete = false
  let mut server_signal = false
  if stage == "orca-serve" {
    for line in output.split("\n") {
      let result = @json.parse(line.to_owned()) catch { _ => Json::null() }
      if field(result, "kind") ==
        Some(Json::string("orca-env-devsy-server-exit")) &&
        field(result, "runId") == Some(Json::string(recording_run_id)) &&
        field(result, "number") ==
        Some(Json::number((status - 128).to_double())) &&
        status > 128 &&
        status <= 255 {
        server_signal = true
      }
      let connection = field(result, "connection").unwrap_or(result)
      if field(connection, "pairingCode") is Some(Json::String(pairing)) &&
        pairing != "" {
        if pairing.length() > 65536 {
          output_protection_incomplete = true
        } else {
          add_protected_secret(output_secrets, pairing)
        }
      }
    }
  }
  let detail = if output_protection_incomplete {
    progress.details_truncated = true
    "error detail unavailable because server protection values exceed the limit\n[error details incomplete or truncated]"
  } else {
    diagnostic_text(
      progress.failure_detail(),
      environment?,
      protected_secrets=output_secrets,
    )
  }
  let observed_status = if server_signal { 128 - status } else { status }
  progress_message(
    label +
    ": " +
    (if observed_status == 0 {
      "done"
    } else {
      "failed (exit \{observed_status})"
    }) +
    " (" +
    progress_timing(started) +
    ")",
  )
  if status == 0 &&
    (
      !progress.failures.is_empty() ||
      progress.details_truncated ||
      (stage == "orca-serve" && !progress.recent.is_empty())
    ) {
    save_diagnostic(
      stage,
      if stage == "orca-serve" {
        "stderr"
      } else {
        "warning"
      },
      error_message=detail,
      details_truncated=progress.details_truncated,
      evidence?=context,
      evidence_stable_operation=true,
      environment?,
      protected_secrets=output_secrets,
      recording~,
    )
  }
  save_diagnostic(
    stage,
    if status == 0 {
      "success"
    } else {
      "exit-error"
    },
    exit_code=observed_status,
    duration_ms=(@env.now() - started).to_double(),
    error_message?=if status == 0 { None } else { Some(detail) },
    details_truncated=progress.details_truncated,
    evidence?=context,
    evidence_stable_operation=true,
    environment?,
    protected_secrets=output_secrets,
    error_type?=if status == 0 || !recording {
      None
    } else if observed_status < 0 {
      Some("signal")
    } else {
      Some(process_error_type(output + "\n" + errors))
    },
    recording~,
  )
  (observed_status, output, detail)
}

