async fn save_diagnostic(
  stage : String,
  status : String,
  exit_code? : Int32,
  error_type? : String,
  phase? : String,
  duration_ms? : Double,
  attempt? : Int32,
  retry_delay_ms? : Int32,
  timeout_ms? : Int32,
  os_errno? : Int32,
  source? : CreateEvidence,
  error_message? : String,
  details_truncated~ : Bool = false,
  tunnel_directory? : String,
  expected_workspace_uid? : String,
  observed_workspace_uid? : String,
  evidence? : Json,
  evidence_incomplete~ : Bool = false,
  evidence_stable_activity~ : Bool = false,
  evidence_stable_operation~ : Bool = false,
  run_completeness? : String,
  recording? : Bool,
  environment? : Map[String, String],
  protected_secrets? : Array[String],
) -> Unit {
  if !recording.unwrap_or(
      @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
    ) {
    return
  }
  diagnostic_run_has_events.val = true
  let event_time = @env.now()
  let event : Json = {
    "stage": stage,
    "status": status,
    "time": event_time.to_string(),
    "runId": recording_run_id,
    "adapterVersion": version,
  }
  if create_recording.attempt > 0 {
    set_field(
      event,
      "createAttempt",
      Json::number(create_recording.attempt.to_double()),
    )
    set_field(event, "createPhase", Json::string(create_recording.phase))
  }
  let process_environment = @env.get_env_vars()
  let secrets = [] + protected_secrets.unwrap_or([])
  if environment is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if tunnel_directory is Some(directory) &&
    diagnostic_workspace_environments.get(directory) is Some(environment) {
    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
      secrets.push(secret)
    }
  }
  if error_message is Some(message) {
    let message = diagnostic_text(
      message,
      environment=process_environment,
      protected_secrets=secrets,
    )
    set_field(event, "errorMessage", Json::string(message))
    set_field(
      event,
      "detailsTruncated",
      Json::boolean(
        details_truncated ||
        message == "[error details incomplete or truncated]" ||
        message.has_suffix("\n[error details incomplete or truncated]"),
      ),
    )
  }
  if tunnel_directory is Some(directory) {
    set_field(
      event,
      "tunnelDirectory",
      Json::string(
        diagnostic_text(
          directory,
          environment=process_environment,
          protected_secrets=secrets,
        ),
      ),
    )
  }
  for
    pair in [
      ("expectedWorkspaceUid", expected_workspace_uid),
      ("observedWorkspaceUid", observed_workspace_uid),
    ] {
    if pair.1 is Some(value) {
      set_field(
        event,
        pair.0,
        Json::string(
          diagnostic_text(
            value,
            environment=process_environment,
            protected_secrets=secrets,
          ),
        ),
      )
    }
  }
  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
  if source is Some(evidence) {
    let value = evidence.to_json()
    if value.stringify().length() <= 65536 {
      set_field(
        event,
        "source",
        diagnostic_json(
          value,
          process_environment,
          secrets,
          evidence_truncated,
          0,
          stable_activity=evidence_stable_activity,
        ),
      )
    } else {
      evidence_truncated.val = true
    }
  }
  if evidence is Some(value) {
    if value.stringify().length() <= 65536 {
      set_field(
        event,
        "evidence",
        diagnostic_json(
          value,
          process_environment,
          secrets,
          evidence_truncated,
          0,
          stable_activity=evidence_stable_activity,
          secret_states=stage == "server-environment",
          stable_operation=evidence_stable_operation,
        ),
      )
    } else {
      evidence_truncated.val = true
    }
  }
  if evidence_truncated.val {
    set_field(event, "evidenceTruncated", Json::boolean(true))
    set_field(event, "completeness", Json::string("partial"))
  }
  if details_truncated ||
    evidence_truncated.val ||
    (
      error_message is Some(message) &&
      message.contains("[error details incomplete or truncated]")
    ) {
    diagnostic_recording_health.run_partial = true
  }
  if run_completeness is Some(value) {
    set_field(event, "runCompleteness", Json::string(value))
  }
  if os_errno is Some(code) && code > 0 && code < 4096 {
    set_field(event, "osErrno", Json::number(code.to_double()))
  }
  if exit_code is Some(code) {
    set_field(event, "exitCode", Json::number(code.to_double()))
  }
  for pair in [("errorType", error_type), ("phase", phase)] {
    if pair.1 is Some(text) {
      set_field(event, pair.0, Json::string(text))
    }
  }
  if duration_ms is Some(value) {
    set_field(event, "durationMs", Json::number(value))
  }
  if attempt is Some(value) {
    set_field(event, "attempt", Json::number(value.to_double()))
  }
  if timeout_ms is Some(value) {
    set_field(event, "timeoutMs", Json::number(value.to_double()))
  }
  if retry_delay_ms is Some(value) {
    set_field(event, "retryDelayMs", Json::number(value.to_double()))
  }
  let failed = error_type is Some(_) ||
    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
      status,
    )
  if diagnostic_pending.length() >= 64 {
    let mut evict = -1
    if failed {
      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
        if !diagnostic_pending[index].failed {
          evict = index
          break
        }
      }
      if evict < 0 &&
        diagnostic_pending_inflight.val < diagnostic_pending.length() {
        evict = diagnostic_pending_inflight.val
      }
    }
    if evict < 0 {
      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
      return
    }
    let removed = diagnostic_pending.remove(evict)
    diagnostic_pending.push({ event, failed, time: event_time, })
    diagnostic_recording_failed(
      "buffer_full",
      phase="buffer",
      event_time=removed.time,
    )
    try_flush_diagnostic_recording()
    return
  }
  diagnostic_pending.push({ event, failed, time: event_time, })
  try_flush_diagnostic_recording()
}

///|
async fn try_flush_diagnostic_recording() -> Unit {
  if diagnostic_write_active.val ||
    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
    return
  }
  diagnostic_write_active.val = true
  defer {
    diagnostic_write_active.val = false
  }
  let mut failure_phase = "directory"
  let mut health_changed = false
  @async.with_timeout(50, async fn() {
    let dir = adapter_state_home()
    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
    @fs.chmod(dir, 0o700)
    let path = dir + "/events.jsonl"
    let lock_path = dir + "/events.lock"
    failure_phase = "lock"
    if @fs.exists(lock_path) &&
      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
      return
    }
    let lock = @fs.open(
      lock_path,
      mode=ReadWrite,
      create_mode=OpenOrCreate,
      permission=0o600,
    )
    defer lock.close()
    if !lock.try_lock(Exclusive) {
      diagnostic_recording_warning("lock_busy", phase=failure_phase)
      return
    }
    failure_phase = "inspect"
    if @fs.exists(path) &&
      @fs.kind(path, follow_symlink=false) != @fs.FileKind::Regular {
      diagnostic_recording_warning("invalid_store", phase=failure_phase)
      return
    }
    let mut prefix = ""
    let mut replace = false
    let mut prefix_markers = 0
    let mut retained : String? = None
    let terminal = diagnostic_pending
      .iter()
      .any(pending => {
        field(pending.event, "stage") == Some(Json::string("diagnostic-run")) &&
        field(pending.event, "status") == Some(Json::string("finished"))
      })
    if @fs.exists(path) {
      let file = @fs.open(path, mode=ReadOnly)
      defer file.close()
      let size = file.size()
      if size > 262144L {
        let marker = diagnostic_recording_event("rotated", "retention_limit")
        set_field(
          marker,
          "missingThroughTime",
          Json::string(@env.now().to_string()),
        )
        set_field(marker, "missingRange", Json::string("unknown"))
        let records = diagnostic_retained_records(file, size)
        retained = Some(records)
        prefix = marker.stringify() + "\n" + records
        prefix_markers += 1
        replace = true
      } else if size > 0L {
        let tail = FixedArray::make(1, b'\x00')
        guard file.read_at(tail, position=size - 1L) == 1 else {
          raise AdapterError("Unable to inspect diagnostic record boundary")
        }
        if tail[0] != b'\n' {
          let bytes = FixedArray::make(size.to_int(), b'\x00')
          let read = file.read_at(bytes, position=0L)
          let mut complete = read
          while complete > 0 && bytes[complete - 1] != b'\n' {
            complete -= 1
          }
          prefix = @utf8.decode_lossy(
            bytes.unsafe_reinterpret_as_bytes()[:complete],
          )
          let marker = diagnostic_recording_event(
            "degraded",
            if read != size.to_int() {
              "short_read"
            } else {
              "incomplete_record"
            },
          )
          set_field(marker, "missingRange", Json::string("unknown"))
          prefix += marker.stringify() + "\n"
          prefix_markers += 1
          retained = Some(
            @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:complete]),
          )
          replace = true
        }
      }
      if terminal && retained is None {
        let bytes = FixedArray::make(size.to_int(), b'\x00')
        let read = file.read_at(bytes, position=0L)
        if read != size.to_int() {
          raise AdapterError("Unable to inspect complete diagnostic records")
        }
        retained = Some(@utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()))
      }
    } else if terminal {
      retained = Some("")
    }
    if retained is Some(records) &&
      diagnostic_current_run_count(records) < diagnostic_run_written_count.val {
      diagnostic_recording_health.run_partial = true
    }
    if terminal && diagnostic_recording_health.run_partial {
      for pending in diagnostic_pending {
        if field(pending.event, "stage") == Some(Json::string("diagnostic-run")) &&
          field(pending.event, "status") == Some(Json::string("finished")) {
          set_field(pending.event, "runCompleteness", Json::string("partial"))
        }
      }
    }
    let recorded_drops = diagnostic_recording_health.dropped
    let incident_serial = diagnostic_recording_health.incident_serial
    if recorded_drops > 0 || diagnostic_recording_health.incident {
      let marker = diagnostic_recording_event(
        if recorded_drops > 0 {
          "degraded"
        } else {
          "recovered"
        },
        diagnostic_recording_health.reason,
      )
      if recorded_drops > 0 {
        set_field(
          marker,
          "droppedEvents",
          Json::number(recorded_drops.to_double()),
        )
        set_field(
          marker,
          "missingFromTime",
          Json::string(diagnostic_recording_health.first_dropped.to_string()),
        )
        set_field(
          marker,
          "missingThroughTime",
          Json::string(diagnostic_recording_health.last_dropped.to_string()),
        )
      } else {
        set_field(marker, "completeness", Json::string("complete"))
      }
      if diagnostic_recording_health.phase != "" {
        set_field(
          marker,
          "phase",
          Json::string(diagnostic_recording_health.phase),
        )
      }
      if diagnostic_recording_health.os_errno is Some(code) {
        set_field(marker, "osErrno", Json::number(code.to_double()))
      }
      prefix += marker.stringify() + "\n"
      prefix_markers += 1
    }
    let count = diagnostic_pending.length()
    diagnostic_pending_inflight.val = count
    defer {
      diagnostic_pending_inflight.val = 0
    }
    let records = @buffer.Buffer(size_hint=4096)
    for index in 0..<count {
      records.write_string_utf8(
        diagnostic_pending[index].event.stringify() + "\n",
      )
    }
    let content = prefix + @utf8.decode_lossy(records.to_bytes())
    failure_phase = if replace { "replace" } else { "append" }
    if replace {
      let temporary = path + ".rotate." + proxy_pid().to_string()
      defer (@fs.remove(temporary) catch { _ => () })
      @fs.write_file(temporary, content, permission=0o600)
      @fs.rename(temporary, path, replace=true)
    } else {
      @fs.write_file(
        path,
        content,
        permission=0o600,
        append=true,
        create_mode=OpenOrCreate,
      )
    }
    diagnostic_run_written_count.val += prefix_markers
    for index in 0..<count {
      if field(diagnostic_pending[index].event, "runId") ==
        Some(Json::string(recording_run_id)) {
        diagnostic_run_written_count.val += 1
      }
    }
    for _ in 0..<count {
      ignore(diagnostic_pending.remove(0))
    }
    diagnostic_previous_losses.clear()
    diagnostic_recording_health.dropped -= recorded_drops
    if diagnostic_recording_health.incident_serial == incident_serial {
      diagnostic_recording_health.incident = false
      health_changed = true
    }
  }) catch {
    error =>
      if !@async.is_being_cancelled() {
        diagnostic_recording_warning(
          if error is @async.TimeoutError {
            "store_timeout"
          } else {
            "store_unavailable"
          },
          phase=failure_phase,
          os_errno?=match error {
            @os_error.OSError(code, ..) => Some(code)
            _ => None
          },
        )
      }
  }
  if health_changed {
    publish_diagnostic_health()
    if diagnostic_recording_health.incident {
      publish_diagnostic_health()
    }
  }
}

///|
async fn flush_diagnostic_recording() -> Unit {
  if diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0 {
    return
  }
  @async.with_timeout(1000, async fn() {
    while !diagnostic_pending.is_empty() ||
          diagnostic_recording_health.dropped > 0 {
      try_flush_diagnostic_recording()
      if !diagnostic_pending.is_empty() ||
        diagnostic_recording_health.dropped > 0 {
        @async.sleep(25)
      }
    }
  }) catch {
    error => if @async.is_being_cancelled() { raise error }
  }
}

///|
async fn finish_diagnostic_recording() -> Unit {
  flush_diagnostic_recording()
  if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
    diagnostic_recording_health.run_partial = true
    publish_diagnostic_health()
    return
  }
  if diagnostic_run_has_events.val {
    save_diagnostic(
      "diagnostic-run",
      "finished",
      run_completeness=if diagnostic_recording_health.run_partial {
        "partial"
      } else {
        "complete"
      },
      recording=true,
    )
    flush_diagnostic_recording()
    if !diagnostic_pending.is_empty() || diagnostic_recording_health.dropped > 0 {
      diagnostic_recording_health.run_partial = true
      publish_diagnostic_health()
    }
  }
}

