 253	///|
 254	async fn codex_rpc_response(
 255	  reader : @process.ReadFromProcess,
 256	  id : Int32,
 257	  secrets : Array[String],
 258	) -> Unit {
 259	  let bytes : Array[Byte] = []
 260	  let mut total = 0
 261	  while true {
 262	    let byte = reader.read_exactly(1)[0]
 263	    total += 1
 264	    guard total <= 1048576 else {
 265	      raise AdapterError("Codex refresh output limit")
 266	    }
 267	    if byte == b'\n' {
 268	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
 269	      bytes.clear()
 270	      if field(response, "id") == Some(Json::number(id.to_double())) {
 271	        if field(response, "error") is Some(error) {
 272	          let code = match field(error, "code") {
 273	            Some(Json::Number(value, ..)) => " code " + value.to_string()
 274	            _ => ""
 275	          }
 276	          let message = match field(error, "message") {
 277	            Some(Json::String(value)) =>
 278	              ": " + diagnostic_text(value, protected_secrets=secrets)
 279	            _ => ""
 280	          }
 281	          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
 282	        }
 283	        guard field(response, "result") != None else {
 284	          raise AdapterError("Codex refresh RPC \{id} returned no result")
 285	        }
 286	        return
 287	      }
 288	    } else {
 289	      bytes.push(byte)
 290	    }
 291	  }
 292	}
