async test "server diagnostics distinguish signal termination from the same exit code" {
  let directory = @fs.tmpdir(prefix="orca-env-devsy-server-exit")
  defer cleanup_fixture(directory)
  let install = directory + "/.local/share/orca-env-devsy/orca/current"
  @fs.mkdir(install + "/resources/app.asar/out/cli", recursive=true)
  let bun = command("which", ["bun"], "fixture-bun", recording_override=false)
    .trim()
    .to_owned()
  @fs.symlink(install + "/orca-ide", target=bun)
  let env = @env.get_env_vars()
  env.set("HOME", directory)
  for signalled in [false, true] {
    @fs.write_file(
      install + "/resources/app.asar/out/cli/index.js",
      if signalled {
        "process.kill(process.pid, 'SIGTERM');\n"
      } else {
        "console.error('Orca server terminated by SIGTERM'); process.exit(143);\n"
      },
    )
    let (status, _, detail) = @async.with_timeout(3000, async fn() {
      command_result(
        "sh",
        ["-c", server_launch_script(directory, 12345, Json::empty_object())],
        "orca-serve",
        environment=env,
        recording_override=false,
      )
    })
    assert_eq(status, if signalled { -15 } else { 143 }, msg=detail)
    assert_true(
      detail.contains("Orca server terminated by SIGTERM"),
      msg=detail,
    )
  }
}

