  match field(state, "socketDirectory") {
    Some(Json::String(value)) => value + "/socket"
    _ => directory + "/socket"
  recording : String,
  attempt : Int32,
) -> (String, Json) {
  let socket = @socket.Tcp::connect(
    @socket.Addr::parse("127.0.0.1:" + port.to_string()),
  )
  defer socket.close()
  let peer = read_registration(socket, 4096)
  let connection = required(peer, "connectionId")
  write_registration(socket, {
    "directory": directory,
    "operationId": operation,
    "attempt": attempt,
    "environment": {
      "ORCA_ENV_DEVSY_RECORDING": recording,
      "ACCESS_TOKEN": "fixture-registration-private",
    },
  })
  let reply = read_registration(socket, 4096) catch { _ => Json::null() }
  (connection, reply)
}

