async test "concurrent registration failures retain phase and client correlation" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let root = env.get("XDG_STATE_HOME").unwrap() + "/orca-env-devsy"
  let good = root + "/tunnels/good"
  let missing = root + "/tunnels/missing"
  let locked = root + "/tunnels/locked"
  for path in [good, missing, locked] {
    @fs.mkdir(path, recursive=true)
  }
  for path in [good, locked] {
    @fs.write_file(path + "/state.json", "{}")
  }
  let lock = @fs.open(
    locked + "/environment.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  @async.with_timeout(16000, async fn() {
    @async.with_task_group(async fn(group) {
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let child = @process.spawn(
        group,
        integration_binary(),
        ["--supervisor", root],
        extra_env=env,
        stdout=sink,
        stderr=sink,
        no_wait=true,
      )
      idle_wait_for(async fn() { @fs.exists(root + "/supervisor.json") })
      let descriptor = @json.parse(
        @fs.read_file(root + "/supervisor.json").text(),
      )
      let port = @string.parse_int(required(descriptor, "port"))
      let first = group.spawn(async fn() {
        fixture_registration_request(port, good, "123_4:1", "1", 1)
      })
      let second = group.spawn(async fn() {
        fixture_registration_request(port, missing, "123_4:2", "1", 2)
      })
      let third = group.spawn(async fn() {
        fixture_registration_request(port, locked, "123_4:3", "1", 3)
      })
      let opted_out = group.spawn(async fn() {
        fixture_registration_request(port, missing, "123_4:4", "0", 4)
      })
      let (first_id, first_reply) = first.wait()
      let (second_id, _) = second.wait()
      let (fourth_id, _) = opted_out.wait()
      assert_eq(field(first_reply, "accepted"), Some(Json::boolean(true)))
      let (third_id, _) = third.wait()
      idle_wait_for(async fn() {
        fixture_events(directory)
        .iter()
        .any(event => {
          field(field(event, "evidence").unwrap_or(Json::null()), "operationId") ==
          Some(Json::string("123_4:3"))
        })
      })
      let events = fixture_events(directory)
      for
        (operation, connection, status, phase, path, attempt) in [
          ("123_4:1", first_id, "success", "reply", good, 1),
          ("123_4:2", second_id, "failed", "directory", missing, 2),
          ("123_4:3", third_id, "timeout", "lock", locked, 3),
        ] {
        let matching = events.filter(event => {
          field(event, "stage") == Some(Json::string("supervisor-registration")) &&
          field(field(event, "evidence").unwrap_or(Json::null()), "operationId") ==
          Some(Json::string(operation))
        })
        assert_eq(matching.length(), 1, msg=Json::array(events).stringify())
        assert_eq(field(matching[0], "status"), Some(Json::string(status)))
        assert_eq(field(matching[0], "phase"), Some(Json::string(phase)))
        assert_eq(
          field(matching[0], "attempt"),
          Some(Json::number(attempt.to_double())),
        )
        assert_eq(
          field(matching[0], "tunnelDirectory"),
          Some(Json::string(@fs.realpath(path))),
        )
        assert_eq(
          field(field(matching[0], "evidence").unwrap(), "connectionId"),
          Some(Json::string(connection)),
        )
      }
      assert_false(
        Json::array(events).stringify().contains("fixture-registration-private"),
      )
      assert_false(Json::array(events).stringify().contains("123_4:4"))
      assert_false(Json::array(events).stringify().contains(fourth_id))
      lock.unlock()
      @fs.write_file(root + "/shutdown", "")
      assert_eq(child.wait(), 0)
    })
  })
}

