          Some(Json::number(attempt.to_double())),
        )
        assert_eq(
          field(matching[0], "tunnelDirectory"),
          Some(Json::string(@fs.realpath(path))),
        )
        assert_eq(
          field(field(matching[0], "evidence").unwrap(), "connectionId"),
          Some(Json::string(connection)),
        )
      }
      assert_false(
        Json::array(events).stringify().contains("fixture-registration-private"),
      )
      assert_false(Json::array(events).stringify().contains("123_4:4"))
      assert_false(Json::array(events).stringify().contains(fourth_id))
      lock.unlock()
      @fs.write_file(root + "/shutdown", "")
      assert_eq(child.wait(), 0)
    })
  })
